import { prisma } from '@/lib/prisma'

export async function GET() {

output:
  const user = await auth()
  if (!user) {
    return new NextResponse('Unauthorized', { status: 401 })
  }

  // Fetch billing information for the user
  const billingInfo = await prisma.user.findUnique({
    where: { id: user.id },
    select: { billing: true },
  })

  if (!billingInfo) {
    return new NextResponse('Billing information not found', { status: 404 })
  }

  // Return the billing information
  return NextResponse.json(billingInfo.billing)
}

export async function POST(request: Request) {
  const user = await auth()
  if (!user) {
    return new NextResponse('Unauthorized', { status: 401 })
  }

  // Parse the request body
  const data = await request.json()

  // Update billing information for the user
  const updatedBillingInfo = await prisma.user.update({
    where: { id: user.id },
    data: {
      billing: {
        ...data,
      },
    },
  })

  if (!updatedBillingInfo) {
    return new NextResponse('Failed to update billing information', { status: 500 })
  }

  // Return the updated billing information
  return NextResponse.json(updatedBillingInfo.billing)
}

