import { type NextRequest, NextResponse } from 'next/server'

export const runtime = 'edge'

export async function GET(request: NextRequest) {

output:
  // get the requester's IP address from the request headers
  const ip = request.headers.get('x-edge-location') || ''

  // use a geo database to look up the country of the requester's IP address
  const country = await lookupCountry(ip)

  // return the country as JSON
  return NextResponse.json({ country })
}

async function lookupCountry(ip: string): Promise<string> {
  // use an external API to look up the country of the requester's IP address
  const response = await fetch(`https://ipapi.co/${ip}/json/`)
  const data = await response.json()

  // return the country from the API response
  return data.country
}

