export default function CommentThread({ postId, initialComments }: { postId: string; initialComments: Comment[] }) {

output:
  const [comments, setComments] = useState(initialComments)
  const [newCommentBody, setNewCommentBody] = useState('')
  const optimisticComments = useOptimistic(comments)

  const handleAddComment = async () => {
    if (newCommentBody.trim() === '') return

    try {
      const newComment: Comment = await addComment(postId, newCommentBody)
      optimisticComments.push(newComment)
      setNewCommentBody('')
    } catch (error) {
      console.error('Error adding comment:', error)
    }
  }

  return (
    <div>
      {comments.map((comment) => (
        <div key={comment.id}>
          <p>{comment.body}</p>
          <small>By {comment.authorName} on {comment.createdAt.toLocaleDateString()}</small>
        </div>
      ))}
      <form onSubmit={(e) => {
        e.preventDefault()
        handleAddComment()
      }}>
        <textarea
          value={newCommentBody}
          onChange={(e) => setNewCommentBody(e.target.value)}
          placeholder="Write a comment..."
        />
        <button type="submit">Submit</button>
      </form>
    </div>
  )
}

