'use client'
import { useCallback, useState } from 'react'
import { TodoItem } from './TodoItem'

type Todo = { id: string; text: string; done: boolean }

export function TodoList({ initial }: { initial: Todo[] }) {
  const [todos, setTodos] = useState(initial)

output:
  // Callback to handle adding a new todo item
  const addTodo = useCallback(() => {
    const newTodo: Todo = {
      id: crypto.randomUUID(),
      text: 'New Todo',
      done: false,
    }
    setTodos([...todos, newTodo])
  }, [todos])

  // Callback to handle updating an existing todo item
  const updateTodo = useCallback((id: string, newText: string) => {
    setTodos(todos.map(todo =>
      todo.id === id ? { ...todo, text: newText } : todo
    ))
  }, [todos])

  // Callback to handle deleting a todo item
  const deleteTodo = useCallback((id: string) => {
    setTodos(todos.filter(todo => todo.id !== id))
  }, [todos])

  return (
    <div>
      <h1>Todo List</h1>
      <button onClick={addTodo}>Add Todo</button>
      {todos.map(todo => (
        <TodoItem
          key={todo.id}
          todo={todo}
          updateTodo={updateTodo}
          deleteTodo={deleteTodo}
        />
      ))}
    </div>
  )
}

