import { useState, useRef } from 'react'

interface DropdownMenuProps {
  trigger: React.ReactNode
  items: { label: string; onSelect: () => void }[]
}

export default function DropdownMenu({ trigger, items }: DropdownMenuProps) {

output:
  const [isOpen, setIsOpen] = useState(false)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // Close the menu when clicking outside of it
  const handleClickOutside = (event: MouseEvent) => {
    if (
      dropdownRef.current && !dropdownRef.current.contains(event.target as Node)
    ) {
      setIsOpen(false)
    }
  }

  // Handle keyboard navigation for the dropdown items
  const handleKeyDown = (event: KeyboardEvent) => {
    if (isOpen) {
      switch (event.key) {
        case 'ArrowUp':
          event.preventDefault()
          const currentActiveItem = document.activeElement as HTMLButtonElement
          const previousItem = currentActiveItem.previousElementSibling as HTMLElement | null
          if (previousItem) {
            previousItem.focus()
          }
          break
        case 'ArrowDown':
          event.preventDefault()
          const nextItem = document.activeElement.nextElementSibling as HTMLElement | null
          if (nextItem) {
            nextItem.focus()
          }
          break
        case 'Escape':
          setIsOpen(false)
          break
      }
    }
  }

  // Add event listeners to handle clicks outside and keyboard navigation
  useEffect(() => {
    document.addEventListener('click', handleClickOutside)
    document.addEventListener('keydown', handleKeyDown)

    return () => {
      document.removeEventListener('click', handleClickOutside)
      document.removeEventListener('keydown', handleKeyDown)
    }
  }, [])

  return (
    <div ref={dropdownRef} className="relative">
      {trigger}
      {isOpen && (
        <ul
          className="absolute top-full left-0 w-full bg-white shadow-md rounded-lg z-10"
          tabIndex={0}
        >
          {items.map((item, index) => (
            <li key={index}>
              <button
                onClick={() => {
                  item.onSelect()
                  setIsOpen(false)
                }}
                className="block px-4 py-2 text-left w-full hover:bg-gray-100"
              >
                {item.label}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

