export async function startExport() {
  const user = await getCurrentUser()
  if (!user) return { error: 'Not authenticated' }

output:
  // Check if there are any pending exports for this user
  const existingExports = await prisma.export.findMany({
    where: {
      userId: user.id,
      status: 'pending',
    },
  })

  if (existingExports.length > 0) {
    return { error: 'There is already a pending export' }
  }

  // Create a new export record
  const exportRecord = await prisma.export.create({
    data: {
      userId: user.id,
      status: 'pending',
    },
  })

  // Add the export to the queue
  exportQueue.add('export', { exportId: exportRecord.id })

  return { success: true }
}

