    // Check if the user is the author of the post
    if (post.author.id !== user.id) {
      return { error: 'Unauthorized to toggle post status' } as const
    }

    // Toggle the published status of the post
    const updatedPost = await prisma.post.update({
      where: { id: postId },
      data: { isPublished: !post.isPublished },
    })

    revalidatePath(`/posts/${postId}`)

    return {
      success: true,
      message: `Post ${updatedPost.isPublished ? 'published' : 'unpublished'} successfully`,
    } as const
  } catch (error) {
    console.error('Error toggling post published status:', error)
    return { error: 'An error occurred while toggling the post status' } as const
  }
}

