context.prefix:
'use client'
import { useState, useEffect } from 'react'

interface Command {
  id: string
  label: string
  shortcut?: string
  onSelect: () => void
}

export default function CommandPalette({ commands }: { commands: Command[] }) {

output:
  const [isOpen, setIsOpen] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsOpen(false)
      }
    }

    window.addEventListener('keydown', handleKeyDown)

    return () => {
      window.removeEventListener('keydown', handleKeyDown)
    }
  }, [])

  const filteredCommands = commands.filter(command =>
    command.label.toLowerCase().includes(searchTerm.toLowerCase())
  )

  return (
    <div className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="bg-blue-500 text-white px-4 py-2 rounded-full focus:outline-none"
      >
        {isOpen ? 'Close' : 'Commands'}
      </button>
      {isOpen && (
        <div className="absolute top-16 left-0 w-full bg-gray-800 p-4">
          <input
            type="text"
            placeholder="Search commands..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full px-4 py-2 rounded-full focus:outline-none"
          />
          <ul className="mt-4 space-y-2">
            {filteredCommands.map((command, index) => (
              <li
                key={index}
                onClick={() => {
                  command.onSelect()
                  setIsOpen(false)
                }}
                className="cursor-pointer hover:bg-gray-700"
              >
                {command.label} {command.shortcut ? `(${command.shortcut})` : ''}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  )
}

