// Type-safe event emitter — events typed as a record
type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

output:
  private listeners: Partial<Record<keyof E, ((...args: any[]) => void)[]>> = {}

  on<K extends keyof E>(event: K, listener: (...args: E[K]) => void): this {
    if (!this.listeners[event]) {
      this.listeners[event] = []
    }
    this.listeners[event].push(listener)
    return this
  }

  off<K extends keyof E>(event: K, listener?: ((...args: any[]) => void)): this {
    const listeners = this.listeners[event]
    if (listeners) {
      if (!listener) {
        delete this.listeners[event]
      } else {
        this.listeners[event] = listeners.filter(l => l !== listener)
      }
    }
    return this
  }

  emit<K extends keyof E>(event: K, ...args: E[K]): boolean {
    const listeners = this.listeners[event]
    if (listeners) {
      for (const listener of listeners) {
        listener(...args)
      }
      return true
    }
    return false
  }
}

